python3 -c "
import numpy as np
lines = open('complex_opt2.xyz').read().splitlines()
n = int(lines[0]); print('atoms:', n, '|', lines[1])
at = []
for l in lines[2:]:
    p = l.split(); at.append((p[0], np.array([float(x) for x in p[1:4]])))
Cu = at[0][1]
def d(i): return np.linalg.norm(at[i][1]-Cu)
def ang(i,j):
    v1 = at[i][1]-Cu; v2 = at[j][1]-Cu
    return np.degrees(np.arccos(np.dot(v1,v2)/np.linalg.norm(v1)/np.linalg.norm(v2)))
for name, i in [('N1 lig1',1), ('Npy lig1',22), ('N1 lig2',35), ('Npy lig2',56), ('O nitA',69), ('O nitB',73)]:
    print(f'{name:10s} {at[i][0]} Cu-dist = {d(i):.3f}')
print('trans N1-N1:', round(ang(1,35),1), ' Npy-Npy:', round(ang(22,56),1), ' O-O:', round(ang(69,73),1))
print('bite lig1:', round(ang(1,22),1), ' bite lig2:', round(ang(35,56),1))
for base in [69,73]:
    O,Nn,Ot1,Ot2 = base, base+1, base+2, base+3
    print(f'nitrate@{base}: Cu-O={d(O):.3f}, O-N={np.linalg.norm(at[Nn][1]-at[O][1]):.3f}, N-Ot={np.linalg.norm(at[Nn][1]-at[Ot1][1]):.3f},{np.linalg.norm(at[Nn][1]-at[Ot2][1]):.3f}, Cu...Ot={d(Ot1):.3f},{d(Ot2):.3f}')
"
